/// <reference types="cypress" />

import {
  DemoInLangCatalogueEntry,
  zDemoInLangCatalogueEntry,
} from "../../../src/model/discoverable-demos-schema";

// Shared helpers and fixtures for the "discoverable demos" end-to-end
// tests (Layer A — fully mocked).  See `disco-demos-e2e-tests.md`.
//
// The real catalogue lives behind the `VITE_DEMO_CATALOGUE_BASE` env.var
// and is served by a separately-managed process.  To keep these tests
// deterministic we `cy.intercept` every catalogue request and serve the
// fixtures under `cypress/fixtures/demo-catalogue/` (generated by
// `scripts/refresh-demos-fixtures.sh`).  The URL shapes (from
// `src/model/discoverable-demos.ts`) are:
//
//   ${BASE}/index/all-demos.json               — the catalogue index
//   ${BASE}/<uuid>/<lang>/metadata.json        — per-demo metadata
//   ${BASE}/<uuid>/<lang>/project.zip          — per-demo project zipfile
//   ${BASE}/<uuid>/<lang>/content/description.md
//   ${BASE}/<uuid>/<lang>/content/thumbnail.png
//   ${BASE}/<uuid>/<lang>/content/thumbnail.mp4
//
// We match on the (base-agnostic) tail of each URL.

const kAllDemosFixture = "demo-catalogue/index/all-demos.json";

function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/** A regexp matching the URL of the per-demo resource at the given
 * `tail` (e.g., `"metadata.json"`), capturing the uuid and language. */
function demoResourceRegExp(tail: string): RegExp {
  return new RegExp(`/([^/]+)/([a-z]+)/${escapeRegExp(tail)}$`);
}

function uuidAndLanguageFromUrl(
  url: string,
  re: RegExp
): { uuid: string; language: string } {
  const m = url.match(re);
  if (m == null) {
    throw new Error(`could not extract demo uuid/language from URL "${url}"`);
  }
  return { uuid: m[1], language: m[2] };
}

/** Serve every request for the per-demo resource at the given `tail`
 * from the matching fixture file. */
function interceptDemoResource(tail: string) {
  const re = demoResourceRegExp(tail);
  cy.intercept("GET", re, (req) => {
    const { uuid, language } = uuidAndLanguageFromUrl(req.url, re);
    req.reply({ fixture: `demo-catalogue/${uuid}/${language}/${tail}` });
  });
}

/** Install intercepts so that all discoverable-demos catalogue resources
 * are served from `cypress/fixtures/demo-catalogue/`.  Call this before
 * `cy.visit("/demos")` (or before navigating into the IDE for a project
 * linked to a demo). */
export function interceptDemoCatalogue() {
  cy.intercept("GET", "**/index/all-demos.json", {
    fixture: kAllDemosFixture,
  }).as("demosIndex");

  interceptDemoResource("metadata.json");
  interceptDemoResource("project.zip");
  interceptDemoResource("content/description.md");
  interceptDemoResource("content/thumbnail.png");

  // Preload each video thumbnail as raw bytes (null = Buffer, no decoding),
  // keyed by "uuid/language". This runs in the command queue, before
  // cy.visit triggers any requests, so the map is populated by the time the
  // app asks for them.  Cypress's `req.reply` body supports `ArrayBuffer`
  // for binary, but NOT a Node `Buffer` (a `Uint8Array`): a `Buffer` falls
  // through to the object/JSON path and is serialized as
  // `{"type":"Buffer","data":[...]}`, which the <video> element rejects
  // ("no supported sources").  So convert each fixture's bytes to a
  // standalone `ArrayBuffer` here.
  let videoBytes = new Map<string, ArrayBuffer>();
  cy.fixture(kAllDemosFixture).then((index) => {
    index
      .map(zDemoInLangCatalogueEntry.parse)
      .filter(
        (e: DemoInLangCatalogueEntry) => e.thumbnailVideoExtension != null
      )
      .forEach((e: DemoInLangCatalogueEntry) => {
        const key = `${e.uuid}/${e.language}`;
        cy.fixture(`demo-catalogue/${key}/content/thumbnail.mp4`, null).then(
          (bytes) => {
            videoBytes.set(
              key,
              bytes.buffer.slice(
                bytes.byteOffset,
                bytes.byteOffset + bytes.byteLength
              )
            );
          }
        );
      });
  });

  const videoRe = demoResourceRegExp("content/thumbnail.mp4");
  cy.intercept("GET", videoRe, (req) => {
    const { uuid, language } = uuidAndLanguageFromUrl(req.url, videoRe);
    req.reply({
      statusCode: 200,
      headers: { "content-type": "video/mp4" },
      body: videoBytes.get(`${uuid}/${language}`), // ArrayBuffer — raw binary
    });
  });
}

/** Intercept the catalogue, visit `/demos`, and wait for the index fetch
 * and the header to render. */
export function visitDemosPage() {
  interceptDemoCatalogue();
  cy.visit("/demos/");
  cy.wait("@demosIndex");
  cy.get(".demos-header");
}

/** As `visitDemosPage()`, but first reset the database — for tests which
 * create a project from a demo and then inspect "My projects". */
export function resetAndVisitDemosPage() {
  interceptDemoCatalogue();
  cy.pytchResetDatabase();
  cy.visit("/demos/");
  cy.wait("@demosIndex");
  cy.get(".demos-header");
}

/** Assert that the IDE is showing the demo sidebar (the project is linked
 * to a demo). */
export function assertDemoSidebar() {
  cy.get(".DemoSidebar");
}

